pub const CP_PACKET2:u32=0x80000000; pub const PACKET2_PAD_SHIFT:u32=0; pub const PACKET2_PAD_MASK:u32=0x3fffffff;
// REG_SET is supplied by the surrounding translation unit.
#[inline] pub const fn PACKET2(v:u32)->u32 { CP_PACKET2 | REG_SET(PACKET2_PAD, v) }
#[inline] pub const fn PACKET3(op:u32,n:u32)->u32 { (PACKET_TYPE3<<30)|((op&0xff)<<8)|((n&0x3fff)<<16) }
#[inline] pub const fn PACKET3_COMPUTE(op:u32,n:u32)->u32 { PACKET3(op,n)|(1<<1) }
